using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class Upgrade62Tests {
  static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Call(object o,string name,params object[] args){o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
  public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var errors=new List<string>();Action<bool,string> c=(ok,msg)=>{if(ok)checks.Add(msg);else errors.Add(msg);};try{
   var p=Engine.Starter(4);var r=Engine.Calculate(p);c(r.Valid&&r.Z1==17&&r.Z2==18,"video default:17 balls and18 pockets");r.Model=CadBuilder.Build(r);c(r.Model.Valid,"PTK model valid "+string.Join(";",r.Model.Errors));c(!r.Model.Parts.Any(q=>q.Id.Contains("flex")),"no elastic spline remains");c(r.Model.Parts.Count(q=>q.Id.StartsWith("wave_ball"))==17,"separate spherical working elements");
   var track=WaveFastModel.Track(p);double maxGap=0,minGap=100;for(int step=0;step<33;step++){double phase=Engine.Tau*step/32;for(int i=0;i<17;i++){var b=WaveFastModel.BallCentre(p,i,phase);double camDistance=Math.Sqrt(Math.Pow(b.X+p.Eccentric*Math.Sin(phase),2)+Math.Pow(b.Y-p.Eccentric*Math.Cos(phase),2));c(Math.Abs(camDistance-(p.Radius-p.Eccentric-p.BallDiameter/2))<1e-8,"ball/cam tangent "+step+"/"+i);double best=double.MaxValue;for(int j=0;j<track.Length;j++){var a=track[j];var z=track[(j+1)%track.Length];double dx=z.X-a.X,dy=z.Y-a.Y,k=Math.Max(0,Math.Min(1,((b.X-a.X)*dx+(b.Y-a.Y)*dy)/(dx*dx+dy*dy)));best=Math.Min(best,Math.Sqrt(Math.Pow(b.X-a.X-k*dx,2)+Math.Pow(b.Y-a.Y-k*dy,2)));}double gap=best-p.BallDiameter/2;minGap=Math.Min(minGap,gap);maxGap=Math.Max(maxGap,gap);var q=r.Model.Parts.Single(x=>x.Id=="wave_ball"+i);var moved=PartMotion.Bind(r,q).At(phase,0).Transform(WaveFastModel.BallCentre(p,i,0));c((moved-b).Length<1e-8,"ball follows cage window "+step+"/"+i);}}c(minGap>.07&&maxGap<.12,"normal track clearance: "+Engine.N(minGap)+".."+Engine.N(maxGap));
   foreach(var field in new[]{"BallDiameter","Radius","Eccentric","Thickness","Wall","Shaft","OutputShaft"}){var q=Engine.Clone(p);var f=typeof(Parameters).GetProperty(field);double v=(double)f.GetValue(q,null);f.SetValue(q,field=="BallDiameter"?5.8:field=="Eccentric"?1.1:v+1,null);var rr=Engine.Calculate(q);c(rr.Valid,"parameter accepted "+field);if(rr.Valid){rr.Model=CadBuilder.Build(rr);c(rr.Model.Valid,"parameter geometry "+field);c(CADDocument.Serializer().Serialize(TransmissionExport.Spec(rr.Model))!=CADDocument.Serializer().Serialize(TransmissionExport.Spec(r.Model)),"parameter changes actual geometry "+field);}}
   foreach(int kind in Enumerable.Range(0,13)){var rr=Engine.Calculate(Engine.Starter(kind));rr.Model=CadBuilder.Build(rr);c(rr.Model.Valid,"family valid "+kind);c(rr.Model.Parts.Any(q=>q.Id.EndsWith("_INNER"))&&rr.Model.Parts.Any(q=>q.Id.EndsWith("_OUTER"))&&rr.Model.Parts.Any(q=>q.Id.Contains("_BALL"))&&rr.Model.Parts.Any(q=>q.Id.EndsWith("_CAGE")),"full bearings in family "+kind);c(!rr.Model.Parts.Any(q=>q.Role=="bearing"&&q.BearingSource==null&&q.Analytic==null&&q.Sections.Count==1&&q.Sections[0].Holes.Count==1),"no annular stand-in "+kind);File.WriteAllText(Path.Combine(folder,"family-"+kind+".assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(rr.Model)));}
   PrintExport.Zip(PrintExport.Select(r.Model,null),Path.Combine(folder,"PTK-print.zip"));c(r.Model.Parts.Single(q=>q.Id=="wave_output").SectionUnion,"separator is one connected printable body");WaveDiagram.Export(r.Wave,Path.Combine(folder,"PTK.svg"),false);WaveDiagram.Export(r.Wave,Path.Combine(folder,"PTK.dxf"),true);
   var legacy=Engine.Clone(p);legacy.WaveScheme=0;legacy.Ratio=50;legacy.Module=.6;var migrated=ReleaseSupport.Parse(ReleaseSupport.Serialize(legacy));c(migrated.WaveScheme==1&&migrated.Ratio==50&&Engine.Calculate(migrated).Valid,"legacy wave project migrates preserving ratio");foreach(int preset in new[]{1,2,3,4}){var motor=Engine.Clone(p);Engine.SetPreset(motor,preset);c(Engine.Calculate(motor).Valid&&motor.BallDiameter==6&&motor.Ratio==17,"motor preset preserves PTK profile "+preset);}
   var support=Engine.Starter(0);var sr=Engine.Calculate(support);sr.Model=CadBuilder.Build(sr);int originalBalls=sr.Model.Parts.Count(q=>q.Id.Contains("ECCENTRIC_BEARING")&&q.Id.Contains("_BALL"));support.BallCount++;var nr=Engine.Calculate(support);nr.Model=CadBuilder.Build(nr);c(nr.Model.Valid&&nr.Model.Parts.Count(q=>q.Id.Contains("ECCENTRIC_BEARING")&&q.Id.Contains("_BALL"))>originalBalls,"disc bearing ball count changes actual 3D");
   using(var k=new CADKernel()){TransmissionExport.Write(r.Model,Path.Combine(folder,"PTK17.step"),k);var b=new CadAssembly();b.Parts.AddRange(r.Model.Parts.Where(q=>q.Id.StartsWith("wave_output_bearing")));TransmissionExport.Write(b,Path.Combine(folder,"bearing.step"),k);}
   using(var scene=new WpfScene()){scene.SetResult(r,false);scene.SavePng(Path.Combine(folder,"PTK17.png"),1200,900);scene.Hidden.Add("wave_front");scene.Hidden.Add("wave_output");scene.Hidden.Add("wave_back");scene.Hidden.Add("001_MOTOR_REFERENCE");scene.RefreshVisibility();scene.Fit();scene.SavePng(Path.Combine(folder,"PTK17-open.png"),1200,900);scene.UpdatePose(1.4);scene.SavePng(Path.Combine(folder,"PTK17-motion.png"),1200,900);}
   using(var bearingScene=new WpfScene()){var bearingResult=new Result{P=p,Wave=r.Wave,Model=new CadAssembly()};bearingResult.Model.Parts.AddRange(r.Model.Parts.Where(q=>q.Id.StartsWith("wave_output_bearing")));bearingScene.SetResult(bearingResult,false);bearingScene.SavePng(Path.Combine(folder,"bearing.png"),1000,800);}
   using(var form=new TrainDesignerForm()){Call(form,"Reload",new object[]{null});Call(form,"Calculate");var nums=(Dictionary<string,SafeNumber>)Field(form,"stageNumbers");nums["Thickness"].Commit(10);Call(form,"Calculate");var doc=(TransmissionTrain)Field(form,"document");c(doc.Stages[0].Parameters.Thickness==10,"stage edit applies immediately");form.AddStage(4);Call(form,"Calculate");doc=(TransmissionTrain)Field(form,"document");var solution=(TrainSolution)Field(form,"solution");c(doc.Stages.Count==3&&solution.Valid,"add PTK in sequence");c(doc.Stages[1].Parent==doc.Stages[0].Id&&doc.Stages[2].Parent==doc.Stages[1].Id,"insert reconnects following stage");Call(form,"MoveStage",-1);c(((TrainSolution)Field(form,"solution")).Valid,"reorder preserves valid chain");Call(form,"History",false);doc=(TransmissionTrain)Field(form,"document");c(doc.Stages.Count==3,"undo order preserves stages");Call(form,"DeleteStage");c(((TransmissionTrain)Field(form,"document")).Stages.Count==2,"delete reconnects chain");form.ExportStlFile(Path.Combine(folder,"chain.zip"));nums=(Dictionary<string,SafeNumber>)Field(form,"stageNumbers");nums["Thickness"].Text="bad";byte[] before=File.ReadAllBytes(Path.Combine(folder,"chain.zip"));bool refused=false;try{form.ExportStlFile(Path.Combine(folder,"chain.zip"));}catch{refused=true;}c(refused&&before.SequenceEqual(File.ReadAllBytes(Path.Combine(folder,"chain.zip"))),"invalid edit cannot overwrite STL");form.WorkspaceApproveClose();}
   var robot=RobotDocument.Example();var build=RobotCad.Build(robot);c(build.Model.Valid,"robot full bearing build "+string.Join(";",build.Model.Errors));c(build.Model.Parts.Any(q=>q.Analytic!=null&&q.Analytic.Sphere!=null),"robot includes actual bearing balls");c(build.ForExport(false,null).Parts.Any(q=>q.Analytic!=null),"robot exact export preserves analytic bearing bodies");
  }catch(Exception ex){errors.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"upgrade62-results.json"),CADDocument.Serializer().Serialize(new{Passed=errors.Count==0,Checks=checks.Count,Failures=errors}));return errors.Count==0?0:1;}
 }
